<?php require_once __DIR__.'/includes/bootstrap.php';$n=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();$msg='';
if($n&&$_SERVER['REQUEST_METHOD']==='POST')$msg='Administrator already exists. Delete this file.';
elseif(!$n&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$user=trim($_POST['username']??'admin');$pass=$_POST['password']??'';if(!$name||!$user||strlen($pass)<12)$msg='Enter all fields and use a password of at least 12 characters.';else{$s=$pdo->prepare("INSERT INTO users(username,password_hash,full_name,role) VALUES(?,?,?,'admin')");$s->execute([$user,password_hash($pass,PASSWORD_DEFAULT),$name]);$msg='Administrator created. Sign in and delete setup_admin.php.';}}
page_header('Initial setup');?><section class="panel narrow"><p class="eyebrow">ONE-TIME SETUP</p><h1>Create administrator</h1><p class="muted">Create the first system administrator, then remove this setup page.</p><?php if($msg):?><div class="alert info"><?=e($msg)?></div><?php endif;?><?php if(!$n):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Full name<input name="full_name" required></label><label>Username<input name="username" value="admin" required></label><label>Password (12+ characters)<input name="password" type="password" minlength="12" required></label><button class="btn primary">Create administrator</button></form><?php endif;?></section><?php page_footer();?>